namespace App\Filament\RelationManagers;

use App\Models\Attachment;
use Filament\Actions\Action;
use Filament\Actions\BulkActionGroup;
use Filament\Actions\CreateAction;
use Filament\Actions\DeleteAction;
use Filament\Actions\DeleteBulkAction;
use Filament\Forms\Components\FileUpload;
use Filament\Resources\RelationManagers\RelationManager;
use Filament\Schemas\Schema;
use Filament\Tables;
use Filament\Tables\Table;
use Illuminate\Support\Facades\URL;

/**
 * Attachments relation manager (Fixzy SysMaker generated code).
 *
 * N files per record on the private `local` disk. Uploads are recorded
 * with who/when metadata; downloads go through a short-lived signed
 * route so files are never exposed via public URLs.
 *
 * Options below are compiled at generation time from the table's
 * attachment settings (max files, allowed types, max size).
 */
class AttachmentsRelationManager extends RelationManager
{
    protected static string $relationship = 'attachments';

    protected static ?string $title = 'Attachments';

    /** Compiled options (generation-time). */
    public const MAX_FILES = 10;

    public const MAX_SIZE_KB = 10240;

    /** @var array<int, string> Empty = any type allowed. */
    public const ALLOWED_TYPES = ['pdf', 'png', 'docx'];

    /**
     * File upload form enforcing the max-files, size and MIME-type limits.
     *
     * @param  Schema  $schema  The relation form schema.
     * @return  Schema  The schema with the upload field.
     */
    public function form(Schema $schema): Schema
    {
        $field = FileUpload::make('file')
            ->label('File')
            ->multiple()
            ->maxFiles(self::MAX_FILES)
            ->maxSize(self::MAX_SIZE_KB)
            ->storeFiles(false)
            ->directory('attachments')
            ->disk('local')
            ->required();

        if (count(self::ALLOWED_TYPES) > 0) {
            $field->acceptedFileTypes(self::ALLOWED_TYPES);
        }

        return $schema->components([$field]);
    }

    /**
     * Attachment list with name, size and MIME columns.
     *
     * @param  Table  $table  The relation table instance.
     * @return  Table  The configured table.
     */
    public function table(Table $table): Table
    {
        return $table
            ->recordTitleAttribute('original_name')
            ->columns([
                Tables\Columns\TextColumn::make('original_name')
                    ->label('File')
                    ->wrap()
                    ->limit(60)
                    ->searchable()
                    ->sortable(),
                Tables\Columns\TextColumn::make('human_size')
                    ->label('Size')
                    ->sortable(['size']),
                Tables\Columns\TextColumn::make('mime')
                    ->label('Type')
                    ->toggleable(isToggledHiddenByDefault: true),
                Tables\Columns\TextColumn::make('uploader.name')
                    ->label('Uploaded by')
                    ->default('System'),
                Tables\Columns\TextColumn::make('created_at')
                    ->label('Uploaded at')
                    ->dateTime()
                    ->sortable(),
            ])
            ->defaultSort('created_at', 'desc')
            ->headerActions([
                CreateAction::make()
                    ->label('Upload files')
                    ->modalHeading('Upload attachments')
                    ->using(function (array $data): void {
                        $owner = $this->getOwnerRecord();
                        $files = \Illuminate\Support\Arr::wrap($data['file'] ?? []);
                        foreach ($files as $file) {
                            if (blank($file)) {
                                continue;
                            }
                            // storeFiles(false) gives us a TemporaryUploadedFile;
                            // move it onto the private disk ourselves.
                            $stored = $file->store('attachments', 'local');
                            Attachment::create([
                                'record_type' => $owner::class,
                                'record_id' => $owner->getKey(),
                                'file_path' => $stored,
                                'original_name' => $file->getClientOriginalName(),
                                'mime' => $file->getClientMimeType(),
                                'size' => $file->getSize(),
                                'uploaded_by' => auth()->id(),
                            ]);
                        }
                    }),
            ])
            ->actions([
                Action::make('download')
                    ->label('Download')
                    ->icon('heroicon-o-arrow-down-tray')
                    ->url(fn (Attachment $record): string => URL::temporarySignedRoute(
                        'fixzy.attachments.download',
                        now()->addMinutes(30),
                        ['path' => $record->file_path, 'name' => $record->original_name],
                    ))
                    ->openUrlInNewTab(),
                DeleteAction::make()
                    ->after(function (Attachment $record): void {
                        \Illuminate\Support\Facades\Storage::disk('local')->delete($record->file_path);
                    }),
            ])
            ->bulkActions([
                BulkActionGroup::make([
                    DeleteBulkAction::make()
                        ->after(function (\Illuminate\Support\Collection $records): void {
                            $records->each(function (Attachment $r): void {
                                \Illuminate\Support\Facades\Storage::disk('local')->delete($r->file_path);
                            });
                        }),
                ]),
            ]);
    }
}
